import{_ as t,o as i,c as e,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"CDS Tenctacle - BlueStore","description":"","frontmatter":{"title":"CDS Tenctacle - BlueStore","date":"2024-08-22T00:00:00.000Z","updated":"2024-08-23T00:00:00.000Z","tags":["Ceph","BlueStore","性能优化","分布式存储","数据管理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/CDS_Tenctacle_-_BlueStore.md","filePath":"posts/2024/CDS_Tenctacle_-_BlueStore.md","lastUpdated":1780459816000}'),r={name:"posts/2024/CDS_Tenctacle_-_BlueStore.md"};function n(s,l,p,a,g,u){return i(),e("div",null,[...l[0]||(l[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Blue Store (Tentacle) 项目进展及未来计划</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Adam, Mat Vander Millan (Digital Ocean), Gary, Igor, Sam 等</p><p><strong>会议内容</strong>：</p><p><strong>一、项目进展</strong></p><ol><li><p><strong>性能退化问题</strong>：</p><ul><li>开发了抓取工具，用于捕获OSD操作日志，分析性能退化原因。</li><li>获取了大量操作日志样本，发现实际工作负载与测试环境存在显著差异。</li><li>正在开发重放工具，模拟实际工作负载以进一步分析。</li></ul></li><li><p><strong>RBD碎片化检查</strong>：</p><ul><li>分析了Digital Ocean提供的RBD工作负载，发现存在未预期的碎片化模式。</li><li>计划在Sealon会议上分享相关结果。</li></ul></li><li><p><strong>Blue Store性能优化</strong>：</p><ul><li>优化了KVS线程，减少写操作延迟。</li><li>研究利用rocksdb的管道功能，提高键值排序效率。</li><li>计划进行自定义rocksdb日志修改，实现并行写入和排序。</li></ul></li><li><p><strong>压缩改进</strong>：</p><ul><li>开发了新的压缩算法，允许用户选择压缩程度和CPU资源消耗。</li><li>正在测试RBD工作负载，评估压缩算法的实际效果。</li></ul></li><li><p><strong>对象修改</strong>：</p><ul><li>Gary提出了在读取操作期间修改对象的方案，用于在线进行碎片化或压缩。</li></ul></li><li><p><strong>分配器优化</strong>：</p><ul><li>Igor开发了一种新的分配器，提高了内存组织和队列性能。</li><li>计划进一步研究分配器性能，并针对RBD OSD进行优化。</li></ul></li><li><p><strong>Blue Store与BlueFS的协同工作</strong>：</p><ul><li>计划进行实验，研究在单设备上同时使用Blue Store和BlueFS的可行性。</li></ul></li><li><p><strong>元数据清理</strong>：</p><ul><li>计划开发元数据清理工具，以简化Blue Store使用。</li></ul></li></ol><p><strong>二、未来计划</strong></p><ol><li><p><strong>性能测试</strong>：</p><ul><li>对新的分配器进行性能测试，并评估其适用性。</li><li>收集分配器在长期运行环境中的性能数据。</li></ul></li><li><p><strong>性能计数器</strong>：</p><ul><li>添加性能计数器，以跟踪关键性能指标。</li><li>开发性能分析工具，帮助用户识别性能瓶颈。</li></ul></li><li><p><strong>稀疏读取</strong>：</p><ul><li>与Seagate团队合作，实现稀疏读取功能。</li></ul></li><li><p><strong>其他</strong>：</p><ul><li>优化Blue Store性能。</li><li>支持更多存储类型。</li></ul></li></ol><p><strong>三、行动计划</strong></p><ol><li>继续进行性能退化分析和优化。</li><li>完成RBD碎片化检查和可视化工具开发。</li><li>优化Blue Store性能，包括KVS线程、分配器、压缩等。</li><li>开发元数据清理工具。</li><li>与Seagate团队合作，实现稀疏读取功能。</li></ol><p><strong>四、其他</strong></p><ol><li>讨论了关于分配器的选择和测试问题。</li><li>讨论了关于性能计数器和性能分析工具的开发问题。</li></ol><p><strong>五、会议总结</strong></p><p>本次会议详细讨论了Blue Store项目的进展和未来计划，明确了下一步的工作重点和行动计划。</p>',15)])])}const _=t(r,[["render",n]]);export{c as __pageData,_ as default};
